   458          r_return_val_if_fail (lfile_hashes, false);
   459          r_return_val_if_fail (rfile_hashes, false);
   460          r_return_val_if_fail (equal, false);
   461
   462          *equal = true;
   463          RBinFileHash *fh_l, *fh_r;
   464          RListIter *hiter_l, *hiter_r;
   465          r_list_foreach (lfile_hashes, hiter_l, fh_l) {
   466                  r_list_foreach (rfile_hashes, hiter_r, fh_r) {
   467                          if (strcmp (fh_l->type, fh_r->type)) {
   468                                  continue;
   469                          }
   470                          if (!!strcmp (fh_l->hex, fh_r->hex)) {
   471                                  *equal = false;
   472                                  return true;
   473                          }
   474                  }
   475          }
   476          return true;
   477  }
